import { DEFAULT_PROFILE, DEFAULT_SETTINGS, DEFAULT_SETUP } from './mockData';
import { renderMainMenu, renderProfile, renderSettings, renderSetup } from './screens';
import type { SetupDTO, UiActions, UiScreen, UiSettings } from './types';
import './ui.css';

export class AppUI {
  private screen: UiScreen = 'main';
  private settings = { ...DEFAULT_SETTINGS };
  private setup = { ...DEFAULT_SETUP };
  constructor(private readonly root: HTMLElement, private readonly actions: Partial<UiActions> = {}) { this.render(); }
  navigate = (screen: UiScreen) => { this.screen = screen; this.actions.navigate?.(screen); this.render(); };
  private render() {
    if (this.screen === 'main') this.root.innerHTML = renderMainMenu(DEFAULT_PROFILE);
    else if (this.screen === 'settings') this.root.innerHTML = renderSettings(this.settings);
    else if (this.screen === 'profile') this.root.innerHTML = renderProfile(DEFAULT_PROFILE);
    else this.root.innerHTML = renderSetup(this.screen, this.setup);
    this.bind();
  }
  private bind() {
    this.root.querySelectorAll<HTMLElement>('[data-nav]').forEach(el => el.addEventListener('click', () => this.navigate(el.dataset.nav as UiScreen)));
    this.root.querySelectorAll<HTMLInputElement>('input[type="range"]').forEach(input => input.addEventListener('input', () => { const out=input.parentElement?.querySelector('output'); if(out) out.textContent=`${input.value}%`; }));
    this.root.querySelector<HTMLFormElement>('[data-settings]')?.addEventListener('submit', e => { e.preventDefault(); const f=new FormData(e.currentTarget); this.settings={controlScheme:String(f.get('controlScheme')) as UiSettings['controlScheme'],quality:String(f.get('quality')) as UiSettings['quality'],masterVolume:Number(f.get('masterVolume')),musicVolume:Number(f.get('musicVolume')),effectsVolume:Number(f.get('effectsVolume')),reducedMotion:f.get('reducedMotion')==='on'}; this.actions.saveSettings?.(this.settings); this.navigate('main'); });
    this.root.querySelector<HTMLElement>('[data-start]')?.addEventListener('click', e => { const mode=(e.currentTarget as HTMLElement).dataset.start as 'play'|'custom'|'ranked'; const panel=this.root.querySelector('.panel')!; const read=(name:string)=>panel.querySelector<HTMLSelectElement>(`[name="${name}"]`)?.value; if(mode!=='ranked') this.setup={players:Number(read('players')),bots:Number(read('bots')),holes:Number(read('holes')) as SetupDTO['holes'],courseId:read('course')??'starter-tour'}; this.actions.startMatch?.(mode,this.setup); });
  }
}
